<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <header>
    <div class="hero">
      <p class="eyebrow">Cat FAQ</p>
      <h1>Everything you wanted to know about cats</h1>
      <p>Quick answers about cat behavior, care, and what makes these curious companions so lovable.</p>
    </div>
  </header>

  <main id="main-content">
    <div class="faq-list" aria-label="Frequently asked questions about cats">
      <div class="example">
        <button class="toggle" type="button" aria-expanded="false" aria-controls="cat-answer-1">
          <span class="question">Why do cats knead with their paws?</span>
          <span class="chevron" aria-hidden="true"></span>
        </button>
